*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:            #0f1117;
  --surface:       #1a1d27;
  --surface-hover: #22263a;
  --border:        #2e3248;
  --border-focus:  #7c83f5;
  --accent:        #7c83f5;
  --accent-hover:  #9da3f7;
  --text-primary:  #e8eaf6;
  --text-secondary:#9195b0;
  --error:         #f28b82;
  --success:       #81c995;
  --radio-size:    20px;
}

body {
  background-color: var(--bg);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

/* ── Skip link ────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 0.5rem;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 6px 6px;
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 0;
}

/* ── Card ─────────────────────────────────────────────── */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 520px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: 1.75rem;
  color: var(--text-primary);
}

/* ── Form field wrapper ───────────────────────────────── */
.form-field {
  margin-bottom: 2rem;
}

/* ── Fieldset / legend ────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
}

legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.375rem;
  display: flex;
  align-items: baseline;
  gap: 0.25rem;
}

.required-marker {
  color: var(--accent);
  font-size: 1.1em;
}

.required-note {
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
}

/* ── Radio options ────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.radio-option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.radio-option:hover {
  background: var(--surface-hover);
  border-color: var(--accent);
}

/* custom radio visuals */
.radio-option input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: var(--radio-size);
  height: var(--radio-size);
  border: 2px solid var(--border);
  border-radius: 50%;
  background: var(--bg);
  cursor: pointer;
  flex-shrink: 0;
  position: relative;
  transition: border-color 0.15s ease;
}

.radio-option input[type="radio"]::after {
  content: "";
  position: absolute;
  inset: 3px;
  border-radius: 50%;
  background: transparent;
  transition: background 0.15s ease;
}

.radio-option input[type="radio"]:checked {
  border-color: var(--accent);
}

.radio-option input[type="radio"]:checked::after {
  background: var(--accent);
}

/* highlight the row when selected */
.radio-option:has(input:checked) {
  border-color: var(--accent);
  background: var(--surface-hover);
}

/* focus ring */
.radio-option input[type="radio"]:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

.radio-option label {
  cursor: pointer;
  font-size: 0.95rem;
  color: var(--text-primary);
  flex: 1;
  user-select: none;
}

/* ── Error text ───────────────────────────────────────── */
.error-text {
  margin-top: 0.75rem;
  font-size: 0.875rem;
  color: var(--error);
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.error-text::before {
  content: "⚠";
  font-size: 0.9em;
}

/* ── Submit button ────────────────────────────────────── */
.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease, outline-offset 0.1s;
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background: var(--accent-hover);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

/* ── Status message ───────────────────────────────────── */
.status-message {
  margin-top: 1.25rem;
  font-size: 0.9rem;
  min-height: 1.5em;
  text-align: center;
}

.status-message.success {
  color: var(--success);
}

/* ── Fieldset invalid state ───────────────────────────── */
fieldset.invalid .radio-option {
  border-color: var(--error);
}

fieldset.invalid legend {
  color: var(--error);
}

/* ── Reflow / narrow viewports ────────────────────────── */
@media (max-width: 360px) {
  .card {
    padding: 1.5rem 1rem;
  }
}

/* ── Reduced motion ───────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Forced Colors (high contrast) ───────────────────── */
@media (forced-colors: active) {
  .radio-option {
    border: 1px solid ButtonText;
  }
  .radio-option:has(input:checked) {
    border-color: Highlight;
  }
  .btn-submit {
    forced-color-adjust: auto;
  }
}
