+  border: none;
+  padding: 0;
+}
+
+legend {
+  font-size: 1rem;
+  font-weight: 600;
+  color: var(--text-primary);
+  margin-bottom: 0.375rem;
+  display: flex;
+  align-items: baseline;
+  gap: 0.25rem;
+}
+
+.required-marker {
+  color: var(--accent);
+  font-size: 1.1em;
+}
+
+.required-note {
+  font-size: 0.8rem;
+  color: var(--text-secondary);
+  margin-bottom: 1.25rem;
+}
+
+/* ── Radio options ────────────────────────────────────── */
+.radio-options {
+  display: flex;
+  flex-direction: column;
+  gap: 0.625rem;
+}
+
+.radio-option {
+  display: flex;
+  align-items: center;
+  gap: 0.75rem;
+  padding: 0.75rem 1rem;
+  border: 1px solid var(--border);
+  border-radius: 8px;
+  cursor: pointer;
+  transition: background 0.15s ease, border-color 0.15s ease;
+}
+
+.radio-option:hover {
+  background: var(--surface-hover);
+  border-color: var(--accent);
+}
+
+/* custom radio visuals */
+.radio-option input[type="radio"] {
+  appearance: none;
+  -webkit-appearance: none;
+  width: var(--radio-size);
+  height: var(--radio-size);
+  border: 2px solid var(--border);
+  border-radius: 50%;
+  background: var(--bg);
+  cursor: pointer;
+  flex-shrink: 0;
+  position: relative;
+  transition: border-color 0.15s ease;
+}
+
+.radio-option input[type="radio"]::after {
+  content: "";
+  position: absolute;
+  inset: 3px;
+  border-radius: 50%;
+  background: transparent;
+  transition: background 0.15s ease;
+}
+
+.radio-option input[type="radio"]:checked {
+  border-color: var(--accent);
+}
+
+.radio-option input[type="radio"]:checked::after {
+  background: var(--accent);
+}
+
+/* highlight the row when selected */
+.radio-option:has(input:checked) {
+  border-color: var(--accent);
+  background: var(--surface-hover);
+}
+
+/* focus ring */
+.radio-option input[type="radio"]:focus-visible {
+  outline: 3px solid var(--border-focus);
+  outline-offset: 3px;
+}
+
+.radio-option label {
+  cursor: pointer;
+  font-size: 0.95rem;
+  color: var(--text-primary);
+  flex: 1;
+  user-select: none;
+}
+
+/* ── Error text ───────────────────────────────────────── */
+.error-text {
+  margin-top: 0.75rem;
+  font-size: 0.875rem;
+  color: var(--error);
+  display: flex;
+  align-items: center;
+  gap: 0.4rem;
+}
+
+.error-text::before {
+  content: "⚠";
+  font-size: 0.9em;
+}
+
+/* ── Submit button ────────────────────────────────────── */
+.btn-submit {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 100%;
+  padding: 0.75rem 1.5rem;
+  background: var(--accent);
+  color: #fff;
+  font-size: 1rem;
+  font-weight: 600;
+  border: 2px solid transparent;
+  border-radius: 8px;
+  cursor: pointer;
+  transition: background 0.15s ease, outline-offset 0.1s;
+  letter-spacing: 0.01em;
+}
+
+.btn-submit:hover {
+  background: var(--accent-hover);
+}
+
+.btn-submit:focus-visible {
+  outline: 3px solid var(--border-focus);
+  outline-offset: 3px;
+}
+
+/* ── Status message ───────────────────────────────────── */
+.status-message {
+  margin-top: 1.25rem;
+  font-size: 0.9rem;
+  min-height: 1.5em;
