const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

const dir = '/workspace/sandbox/skills/building-accessible-ui/radio-button-group--framework-vanilla-js--style-dark/claude-sonnet-4.6__s1';
const html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');
// Inline CSS and JS so the page works without a server
const css  = fs.readFileSync(path.join(dir, 'styles.css'), 'utf8');
const js   = fs.readFileSync(path.join(dir, 'main.js'),   'utf8');

const inlined = html
  .replace('<link rel="stylesheet" href="styles.css">', `<style>${css}</style>`)
  .replace('<script src="main.js"></script>',           `<script>${js}</script>`);

(async () => {
  const b    = await chromium.launch();
  const page = await b.newPage();
  await page.setContent(inlined, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r = await page.evaluate(async () => await window.axe.run());
  await b.close();

  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help,
                           targets: v.nodes.map(n => n.target) })),
    bp:   bp.map(v   => ({ id: v.id,                 help: v.help,
                           targets: v.nodes.map(n => n.target) })),
  }, null, 2));

  process.exit(wcag.length ? 1 : 0);
})();
EOF
